changeSet.sql:
CREATE OR ALTER TRIGGER trg_lesson_completion_denorm ON lesson_completion AFTER INSERT, DELETE AS BEGIN DECLARE @AffectedEnrollments TABLE (enrollment_id BIGINT);
INSERT INTO @AffectedEnrollments (enrollment_id) SELECT enrollment_id FROM inserted UNION SELECT enrollment_id FROM deleted;
UPDATE e SET completed_lessons_count = ( SELECT COUNT(*) FROM lesson_completion lc WHERE lc.enrollment_id = e.id ) FROM enrollment e INNER JOIN @AffectedEnrollments ae ON e.id = ae.enrollment_id; END;
